mapper.select:
select 
from oa_sign_file_evidence
where document_id = #{documentId}
  and document_version = #{documentVersion}
order by evidence_id

select 
from oa_sign_file_evidence
where document_id = #{documentId}
  and document_version = #{documentVersion}
  and evidence_type = #{evidenceType}
limit 1

mapper.delete:
delete from oa_sign_file_evidence
where package_id = #{packageId}
  and document_version = #{documentVersion}
